mapper.select:
UPDATE plab_match
SET
    current_player_cnt = #{currentPlayerCnt},
    stadium_name = #{stadiumName},
    sub_type = #{subType, typeHandler=org.apache.ibatis.type.EnumTypeHandler}
WHERE match_no = #{matchNo}

mapper.update:
UPDATE match_subscription
SET is_notified = true
WHERE subscription_no = #{subscriptionNo}
